            rows = [line for line in trace.splitlines() if line.startswith('| ') and re.search(r'\]\(#' + re.escape(item['slug']) + r'-q-\d+\)', line)]
            self.assertEqual(len(question_blocks), len(rows), item['employer'])
            mapped_trace = '\n'.join(rows)
